	'ke3aadbd5' => 'Three planners, one of them yours.',
	'ke444f739' => 'TAG',
	'ke727b009' => 'Archive',
	'ke7696aac' => 'We design bespoke routes for couples who want to travel together with calm minds and unhurried days, with one dedicated planner from your first call to the flight home.',
	'ke94993e9' => 'Rural guesthouses',
	'keb9d430e' => 'Peaceful coral reef tidal walks and swimming',
	'kecaba4bc' => 'Forty-five minutes by video, free, Monday to Saturday 09:00–19:00 CET. Bring your dates if you have them and your questions if you don’t. Within seven days you will have a first route and a fee for the whole plan.',
